    font-size:clamp(1.8rem,4vw,2.6rem);font-weight:400;letter-spacing:.02em;
  }
  .section-head .rule{
    width:56px;height:2px;background:var(--gold);margin:1.2rem auto 0;
  }

  /* ---------- PILLARS ---------- */
  .pillars{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:2rem;}
  .pillar{
    background:#fff;border-top:3px solid var(--accent);
    padding:2.2rem 1.8rem;box-shadow:0 2px 14px rgba(0,0,0,.06);
  }
  .pillar h3{font-size:1.15rem;letter-spacing:.06em;margin-bottom:.8rem;}
  .pillar p{font-size:.95rem;color:var(--muted);}

  /* ---------- QUOTE ---------- */
  .quote-band{
    background:var(--ink);color:var(--paper);
    padding:4.5rem 2rem;text-align:center;
  }
  .quote-band blockquote{
