  }
  .quote-band cite{
    display:block;margin-top:1.4rem;font-size:.78rem;
    letter-spacing:.25em;text-transform:uppercase;color:var(--gold);font-style:normal;
  }

  /* ---------- EVENTS ---------- */
  .events{display:grid;gap:1.4rem;}
  .event{
    display:flex;gap:1.6rem;align-items:flex-start;
