  .join p{max-width:560px;margin:0 auto 2rem;color:#f0d9d9;}
  .join .btn{background:var(--paper);color:var(--accent);border-color:var(--paper);}
  .join .btn:hover{background:transparent;color:var(--paper);border-color:var(--paper);}

  /* ---------- FOOTER ---------- */
  footer{
    background:var(--ink);color:#b9b2a6;
    padding:3rem 2rem;text-align:center;font-size:.82rem;
  }
  footer .brand{color:var(--paper);letter-spacing:.2em;text-transform:uppercase;margin-bottom:.8rem;}
  footer .brand span{color:var(--gold);}
  footer p{max-width:520px;margin:0 auto;}

  @media(max-width:640px){
    nav{padding:0 1rem;}
    nav ul{gap:.9rem;}
    nav a{font-size:.68rem;letter-spacing:.06em;}
    .event{flex-direction:column;gap:.6rem;}
    .event .date{width:auto;text-align:left;}
  }
</style>
</head>
